from money import dollars
from decimal import Decimal, localcontext
def orders(client,account):
    return [(row["id"],dollars(row["total_cents"])) for row in collect(client,account)]
def grand_total(client,account):
    rows=orders(client,account)
    with localcontext() as ctx:
